AuthProvider:
/**
 * Authentication provider interface
 *
 * @version 0.1.0
 * @since 0.0.1
 * @author AMBROISE PARK Consulting
 */
interface AuthProvider {
    /**
     * Initialize the auth provider
     */
    initialize(): Promise<void>;
    /**
     * Get the current user
     */
    getCurrentUser(): Promise<AuthUser | null>;
    /**
     * Sign in with email and password
     */
    signInWithEmailAndPassword(email: string, password: string): Promise<AuthUser>;
    /**
     * Sign up with email and password
     */
    createUserWithEmailAndPassword(email: string, password: string, metadata?: SignUpMetadata): Promise<AuthUser>;
    /**
     * Sign out the current user
     */
    signOut(): Promise<void>;
    /**
     * Reset password for email
     */
    sendPasswordResetEmail(email: string): Promise<void>;
    /**
     * Update user profile
     */
    updateUserProfile(updates: Partial<AuthUser>): Promise<void>;
    /**
     * Get the current access token
     */
    getAccessToken(): Promise<string | null>;
    /**
     * Refresh the authentication token
     *
     * Throws on provider error (the failure reason must stay visible to callers).
     * Returns `null` only when there is no session or the auth state changed
     * during the refresh (result superseded), never to signal a provider error.
     */
    refreshToken(): Promise<string | null>;
    /**
     * Subscribe to auth state changes
     */
    onAuthStateChanged(callback: (user: AuthUser | null) => void): UnsubscribeFn;
    /**
     * Check if user has a specific role
     */
    hasRole(role: UserRole): Promise<boolean>;
    /**
     * Check if user has access to a feature
     */
    hasFeature(featureId: string): Promise<boolean>;
    /**
     * Check if user has access to a tier
     */
    hasTier(requiredTier: string): Promise<boolean>;
    signInWithEmail(email: string, password: string): Promise<AuthResult | null>;
    createUserWithEmail(email: string, password: string, metadata?: SignUpMetadata): Promise<AuthResult | null>;
    signInWithPartner(partnerId: AuthPartnerId, method?: AuthMethod): Promise<AuthResult | null>;
    linkWithPartner(partnerId: AuthPartnerId, method?: AuthMethod): Promise<AuthResult | null>;
    signInWithGoogleCredential(credential: string): Promise<AuthResult | null>;
    updatePassword(newPassword: string): Promise<void>;
    /**
     * Verify a password reset code from the email callback link.
     * Returns the email address associated with the code.
     * @returns email address, or null if code is invalid/expired
     */
    verifyPasswordResetCode?(code: string): Promise<string | null>;
    /**
     * Confirm a password reset with the code from the email and the new password.
     * After success, user can sign in with the new password.
     */
    confirmPasswordReset?(code: string, newPassword: string): Promise<void>;
    /**
     * Get the password reset redirect path for this provider.
     * Used to build the redirect URL in password reset emails.
     */
    getPasswordResetRedirectUrl?(): string;
    /**
     * Send (again) the address-confirmation email.
     *
     * @param email - Address to confirm. Needed when nobody is signed in (sign-up with
     *   email confirmation leaves no session); providers that can only resend to the
     *   signed-in user ignore it.
     */
    sendEmailVerification(email?: string): Promise<void>;
    /**
     * Confirm a sign-up address with the code from the confirmation email (one-time
     * code), instead of the link. Success signs the user in: the provider keeps the
     * session and fires the auth state change.
     * Implemented by providers that send sign-up codes (Supabase: `verifyOtp`, type
     * `signup`); absent otherwise.
     *
     * @param email - The address that signed up
     * @param code - The code typed by the user
     * @returns The confirmed, signed-in user
     * @throws DoNotDevError (via `wrapAuthError`) on a wrong / expired code or a rate
     *   limit; the provider's code stays in `details.originalCode`
     * @since 0.3.3
     */
    verifyEmailCode?(email: string, code: string): Promise<AuthUser>;
    sendSignInLinkToEmail(email: string, actionCodeSettings?: {
        url: string;
        handleCodeInApp: boolean;
    }): Promise<void>;
    signInWithEmailLink(email: string, emailLink?: string): Promise<AuthResult | null>;
    isSignInWithEmailLink(emailLink?: string): boolean;
    getEmailVerificationStatus(): Promise<{
        status: string;
    }>;
    isEmailVerificationEnabled(): Promise<boolean>;
    reauthenticateWithPassword(password: string): Promise<void>;
    reauthenticateWithProvider(partnerId: AuthPartnerId, method?: AuthMethod): Promise<void>;
    deleteAccount(password?: string): Promise<void>;
    /**
     * List every account of the auth backend (admin apps). The adapter calls its own
     * admin-only `listAuthUsers` server function (`@donotdev/functions`: Supabase
     * `createListAuthUsers`, Firebase `listAuthUsers`), which the app deploys; a
     * non-admin caller is refused by the server. Absent on providers without it.
     *
     * @returns All accounts, every page included
     * @throws DoNotDevError (via `wrapAuthError`) when the call fails or is refused
     * @since 0.3.3
     */
    listUsers?(): Promise<AuthUserSummary[]>;
    /**
     * Set session persistence (remember me) for the next sign-in.
     * Provider-specific: Firebase uses browserLocal/browserSession persistence,
     * Supabase uses persistent or session cookies.
     * Throws when this provider instance cannot honour it (see `supportsRememberMe`).
     *
     * @param remember - true for persistent session, false for session-only
     */
    setRememberMe?(remember: boolean): Promise<void>;
    /**
     * Whether `setRememberMe` works on this instance (e.g. Supabase only with the cookie
     * client). Omitted = it works whenever `setRememberMe` exists.
     */
    supportsRememberMe?(): boolean;
    /**
     * Signed-in state read synchronously from the request cookies, without the auth
     * service. Lets the server render, and the client's hydration pass, show the real
     * signed-in state before the provider has initialised.
     * Display only: never an authorisation decision (the cookie is not verified).
     * Implemented by providers that keep their session in cookies (Supabase via
     * `createBrowserClient`); absent otherwise.
     *
     * @param cookieHeader - The request's `Cookie` header (`a=1; b=2`)
     * @returns The snapshot (`user: null` = signed out), or `null` when the cookies
     *   cannot tell
     */
    readSessionSnapshot?(cookieHeader: string): AuthSessionSnapshot | null;
}

