 * @author AMBROISE PARK Consulting
 */
interface NextConfigOptions {
  /** App config from app.ts - features and SEO will be extracted automatically (required) */
  appConfig: AppConfig;
  /** Debug mode - enables detailed debug logging */
  debug?: boolean;
  /** Verbose logging - shows config/search paths (opt-out, auto-disabled in CI) */
  verbose?: boolean;
  /** Route discovery configuration (uses DRY RouteDiscoveryOptions) */
  routes?: RouteDiscoveryOptions & {
    /** Generate app/** page files (Site template) (default: true) */
    generateAppPages?: boolean;
    /** Routing mode for Next.js */
    routingMode?: 'pages' | 'app';
    /**
     * Generate `src/proxy.next.ts`: server-side redirects for pages whose PageMeta sets
     * `auth`, when the auth session lives in cookies (Supabase `createBrowserClient`).
     * @default true
     */
    generateMiddleware?: boolean;
  };
  /** Internationalization configuration (uses DRY I18nOptions) */
  i18n?: I18nOptions;
  /** Theme configuration (uses DRY ThemeDetectionOptions) */
  themes?: ThemeDetectionOptions;
  /** Asset configuration (uses DRY AssetOptions) */
  assets?: AssetOptions;
  /** Generate route manifest */
  generateManifest?: boolean;
  /** PWA configuration */
  pwa?: PWAOptions;
  /**
   * Ignored on Next (Vite's server shim, `createServerShimPlugin`): Next keeps server-only
   * modules out of client bundles itself
   */
  serverShim?: ServerShimOptions;
  /**
   * Standard Next.js config options, passed through to Next (which validates them).
   * `rewrites`, `redirects` and `headers` are composed with the framework's: `headers` rules
   * come after the framework header policy (last wins). The framework sets no `webpack` or
   * `compiler` config (Next 16 builds with Turbopack): an app's own passes through. Prefer
   * `appConfig.headers` for CSP sources and cache overrides (same option on Vite).
   */
  [key: string]: any;
}

